fn solve(a: i8, b: i8) -> (i8, i8) {
    // We want x + y = a and x - y = b.
    // Adding:  2x = a + b  => x = (a + b) / 2
    // Subtract: 2y = a - b  => y = (a - b) / 2
    //
    // Assumptions guarantee (a+b) and (a-b) are even, so division is exact.
    // Use i16 to avoid any intermediate overflow, then cast back to i8.
    let a16 = a as i16;
    let b16 = b as i16;

    let x = ((a16 + b16) / 2) as i8;
    let y = ((a16 - b16) / 2) as i8;

    (x, y)
}